#include <vector>

// The mean of the scores, or 0.0 when there are none.
double averageScore(const std::vector<int>& scores)
{
    if (scores.empty()) return 0.0;
    int total{ 0 };
    for (std::size_t i{ 0 }; i < scores.size(); ++i)
        total += scores[i];
    return static_cast<double>(total) / static_cast<double>(scores.size());
}

unitTests:
TEST("two scores with a half") { CHECK_NEAR(averageScore({ 3, 4 }), 3.5, 1e-9); }
TEST("three scores") { CHECK_NEAR(averageScore({ 10, 20, 30 }), 20.0, 1e-9); }
TEST("the first score counts") { CHECK_NEAR(averageScore({ 100, 0 }), 50.0, 1e-9); }
TEST("one score") { CHECK_NEAR(averageScore({ 7 }), 7.0, 1e-9); }
TEST("no scores") { CHECK_NEAR(averageScore({}), 0.0, 1e-9); }
TEST("negative scores") { CHECK_NEAR(averageScore({ -5, 2 }), -1.5, 1e-9); }

